+	cpumask_var_t clean_mask;
 };

 /**
-- 
2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
crypto: caam - fix netdev memory leak in dpaa2_caam_probe

When commit 0e1a4d427f58 ("crypto: caam: Unembed net_dev structure in
dpaa2") converted embedded net_device to dynamically allocated pointers,
it added cleanup in dpaa2_dpseci_disable() but missed adding cleanup in
dpaa2_dpseci_free() for error paths.

This causes memory leaks when dpaa2_dpseci_dpio_setup() fails during probe
due to DPIO devices not being ready yet. The kernel's deferred probe
mechanism handles the retry successfully, but the netdevs allocated during
the failed probe attempt are never freed, resulting in kmemleak reports
showing multiple leaked netdev-related allocations all traced back to
dpaa2_caam_probe().

Fix this by preserving the CPU mask of allocated netdevs during setup and
using it for cleanup in dpaa2_dpseci_free(). This approach ensures that
only the CPUs that actually had netdevs allocated will be cleaned up,
avoiding potential issues with CPU hotplug scenarios.

Fixes: 0e1a4d427f58 ("crypto: caam: Unembed net_dev structure in dpaa2")
Signed-off-by: Jianpeng Chang <jianpeng.chang.cn@windriver.com>
Reviewed-by: Breno Leitao <leitao@debian.org>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The bug is a memory leak of per-CPU net_dev structures allocated in dpaa2_dpseci_setup. When commit 0e1a4d427f58 converted the net_device from embedded to dynamically allocated pointers, the cleanup for these allocations was only added in dpaa2_dpseci_disable (called during normal shutdown), but was missing in dpaa2_dpseci_free, which is called in error paths (e.g., when dpaa2_dpseci_dpio_setup fails). Additionally, the local clean_mask used to track allocated netdevs was not stored in the private structure, so it could not be used later for cleanup.

Here is the patch:

 static void dpaa2_dpseci_free(struct dpaa2_caam_priv *priv)
 {
 	struct device *dev = priv->dev;
 	struct fsl_mc_device *ls_dev = to_fsl_mc_device(dev);
-	int err;
+	struct dpaa2_caam_priv_per_cpu *ppriv;
+	int i, err;

 	if (DPSECI_VER(priv->major_ver, priv->minor_ver) > DPSECI_VER(5, 3)) {
 		err = dpseci_reset(priv->mc_io, 0, ls_dev->mc_handle);
 		if (err)
 			dev_err(dev, "dpseci_reset() failed\n");
 	}

+	for_each_cpu(i, priv->clean_mask) {
+		ppriv = per_cpu_ptr(priv->ppriv, i);
+		free_netdev(ppriv->net_dev);
+	}
+	free_cpumask_var(priv->clean_mask);
+
 	dpaa2_dpseci_congestion_free(priv);
 	dpseci_close(priv->mc_io, 0, ls_dev->mc_handle);
 }


 static int __cold dpaa2_dpseci_setup(struct fsl_mc_device *ls_dev)
 {
 	struct device *dev = &ls_dev->dev;
 	struct dpaa2_caam_priv *priv;
 	struct dpaa2_caam_priv_per_cpu *ppriv;
-	cpumask_var_t clean_mask;
 	int err, cpu;
 	u8 i;

 	err = -ENOMEM;
-	if (!zalloc_cpumask_var(&clean_mask, GFP_KERNEL))
-		goto err_cpumask;
-
 	priv = dev_get_drvdata(dev);

+	if (!zalloc_cpumask_var(&priv->clean_mask, GFP_KERNEL))
+		goto err_cpumask;
+
 	priv->dev = dev;
 	priv->dpsec_id = ls_dev->obj_desc.id;

 	/* Get a handle for the DPSECI this interface is associate with */
 	err = dpseci_open(priv->mc_io, 0, priv->dpsec_id, &ls_dev->mc_handle);
 	if (err) {
 		dev_err(dev, "dpseci_open() failed: %d\n", err);
 		goto err_open;
 	}

 	err = dpseci_get_api_version(priv->mc_io, 0, &priv->major_ver,
 				     &priv->minor_ver);
 	if (err) {
 		dev_err(dev, "dpseci_get_api_version() failed\n");
 		goto err_get_vers;
 	}

 	dev_info(dev, "dpseci v%d.%d\n", priv->major_ver, priv->minor_ver);

 	if (DPSECI_VER(priv->major_ver, priv->minor_ver) > DPSECI_VER(5, 3)) {
 		err = dpseci_reset(priv->mc_io, 0, ls_dev->mc_handle);
 		if (err) {
 			dev_err(dev, "dpseci_reset() failed\n");
 			goto err_get_vers;
 		}
 	}

 	err = dpseci_get_attributes(priv->mc_io, 0, ls_dev->mc_handle,
 				    &priv->dpseci_attr);
 	if (err) {
 		dev_err(dev, "dpseci_get_attributes() failed\n");
 		goto err_get_vers;
 	}

 	err = dpseci_get_sec_attr(priv->mc_io, 0, ls_dev->mc_handle,
 				  &priv->sec_attr);
 	if (err) {
 		dev_err(dev, "dpseci_get_sec_attr() failed\n");
 		goto err_get_vers;
 	}

 	err = dpaa2_dpseci_congestion_setup(priv, ls_dev->mc_handle);
 	if (err) {
 		dev_err(dev, "setup_congestion() failed\n");
 		goto err_get_vers;
 	}

