{
	struct dpaa2_caam_priv_per_cpu *ppriv;
	int i;

	for_each_cpu(i, cpus) {
		ppriv = per_cpu_ptr(priv->ppriv, i);
		free_netdev(ppriv->net_dev);
	}
}

